const mounts=new WeakMap()
export function attachIntegrationsInteractions(root,api) {
 if(mounts.has(root))mounts.get(root)()
 let disposed=false
 const commit=(action)=>{const s=api.state();s.integrations=transitionIntegration(integrationState(s),action,{...context(s),view:root.querySelector('[data-integrations-view-root]')?.dataset.integrationsViewRoot,answer:s.answer,answerChoice:s.answerChoice});const target=s.integrations.navigation;s.integrations.navigation=null;if(target)api.navigate(target.view,target.patch);else api.rerender()}
 const click=async event=>{
  const link=event.target.closest?.('[data-integrations-view]');if(link&&root.contains(link)){
   event.preventDefault();event.stopPropagation();const s=api.state(),d=integrationState(s),target={view:link.dataset.integrationsView,patch:JSON.parse(link.dataset.integrationsPatch)}
   if(d.reveal){d.pendingNavigation=target;s.integrations=d;api.rerender()}else api.navigate(target.view,target.patch);return
  }
  const b=event.target.closest?.('[data-integrations-action]');if(!b||!root.contains(b)||b.disabled)return
  event.preventDefault();event.stopPropagation();const type=b.dataset.integrationsAction,data=JSON.parse(b.dataset.integrationsData || '{}'),s=api.state()
  if(type==='copy-recipe'){if(!recipeValid(integrationState(s)))return;try{await navigator.clipboard.writeText(JSON.stringify(integrationState(s).recipe,null,2));s.integrations={...integrationState(s),message:'Рецепт скопирован.'}}catch{s.integrations={...integrationState(s),error:'Clipboard недоступен. Рецепт можно выделить и скопировать из панели.'}}api.rerender();return}
  if(type==='cancel-reveal'){s.integrations={...integrationState(s),pendingNavigation:null};api.rerender();return}
  if(type==='leave-reveal'){const d=integrationState(s),target=d.pendingNavigation;d.reveal=null;d.pendingNavigation=null;s.integrations=d;if(target)api.navigate(target.view,target.patch);else api.rerender();return}
  if(['interaction-draft','interaction-concurrent'].includes(type)){const form=root.querySelector('[data-integrations-form=interaction]');if(form){const draft=Object.fromEntries(new FormData(form));commit({type,data:type==='interaction-concurrent'?{...data,draft}:draft});return}}
  commit({type,data})
 }
 const submit=event=>{const form=event.target;if(!form.matches('[data-integrations-form]'))return;event.preventDefault();event.stopPropagation();const fd=new FormData(form),data={};for(const key of new Set(fd.keys()))data[key]=['projects','operations','modes','capabilities','resources','agents'].includes(key)?fd.getAll(key):fd.get(key);commit({type:form.dataset.integrationsForm,data})}
 const change=async event=>{if(!event.target.matches('[data-integrations-report-file]'))return;event.stopPropagation();const file=event.target.files?.[0];if(!file)return;const s=api.state();try{if(file.size>131072)throw Error('Отчёт больше 128 KiB.');const report=JSON.parse(await file.text());if(disposed)return;commit({type:'local-report',data:{recipe:report.recipe,consumer:report.consumer,contract:report.contract,result:report.result,artifactDigest:report.artifactDigest}})}catch(error){s.integrations={...integrationState(s),error:'Не удалось прочитать JSON отчёта: '+error.message};api.rerender()}}
 root.addEventListener('click',click);root.addEventListener('submit',submit);root.addEventListener('change',change)
 const cleanup=()=>{disposed=true;root.removeEventListener('click',click);root.removeEventListener('submit',submit);root.removeEventListener('change',change);mounts.delete(root)}
 mounts.set(root,cleanup);return cleanup
}

